/**
 * IVX Owner AI smoke E2E (Playwright)
 *
 * Verifies that the public landing surface reaches owner-login from the
 * primary entry points. Real device + Supabase owner flows live in the
 * Maestro suite. This file is intentionally minimal so it can run in a
 * vanilla CI environment without device emulators.
 */
import { test, expect } from '@playwright/test';

test.describe('IVX landing → owner login', () => {
  test('landing exposes owner login entry', async ({ page }) => {
    await page.goto('/');
    await expect(page).toHaveTitle(/IVX|Owner|Rork|Expo/i);
  });

  test('owner login screen renders', async ({ page }) => {
    await page.goto('/login?ownerMode=1');
    // Body should mention "Owner" somewhere on the rendered page.
    const body = await page.locator('body').innerText();
    expect(body.toLowerCase()).toContain('owner');
  });
});

input.command:
bash -lc 'set -euo pipefail
repo="ibb142/ivx-holdings-platform"
auth="Authorization: Bearer $GITHUB_TOKEN"
parent=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/git/ref/heads/main" | jq -r ".object.sha")
base_tree=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/git/commits/$parent" | jq -r ".tree.sha")
flow=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/contents/expo/.maestro/ivx-chat-qa-full.yaml?ref=main" | jq -r .content | tr -d "\n" | base64 -d | perl -0pe "s/^\s+timeout:\s*\d+\s*\n//mg")
launch=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/contents/expo/.maestro/ivx-app-launch.yaml?ref=main" | jq -r .content | tr -d "\n" | base64 -d | perl -0pe "s/^\s+timeout:\s*\d+\s*\n//mg")
owner=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/contents/expo/.maestro/ivx-owner-ai-chat.yaml?ref=main" | jq -r .content | tr -d "\n" | base64 -d | perl -0pe "s/^\s+timeout:\s*\d+\s*\n//mg")
config=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/contents/expo/playwright.config.ts?ref=main" | jq -r .content | tr -d "\n" | base64 -d | perl -0pe "s#baseURL: process\.env\.E2E_BASE_URL \?\? '\''http://localhost:8081'\'',#baseURL: process.env.E2E_BASE_URL ?? '\''https://ivxholding.com'\'',#")
spec=$(cat <<"EOF"
import { expect, test } from '@playwright/test';

/** Verifies the public IVX surface and the unauthenticated IVX IA response path. */
test.describe('IVX production public surface', () => {
  test('landing page renders', async ({ page }) => {
    const response = await page.goto('/');
    expect(response?.ok()).toBe(true);
    await expect(page.locator('body')).not.toBeEmpty();
  });

  test('production health identifies the deployed service', async ({ request }) => {
    const response = await request.get('https://api.ivxholding.com/health');
    expect(response.ok()).toBe(true);
    const health: { status?: string; commit?: string } = await response.json();
    expect(health.status).toBe('healthy');
    expect(health.commit).toMatch(/^[a-f0-9]{7,40}$/);
  });

  test('public IVX IA answers a deterministic request', async ({ request }) => {
    const response = await request.post('https://api.ivxholding.com/api/public/chat', {
      data: { message: '7 multiplied by 8' },
    });
    expect(response.ok()).toBe(true);
    const payload: { ok?: boolean; answer?: string } = await response.json();
    expect(payload.ok).toBe(true);
    expect(payload.answer).toContain('56');
  });
});
EOF
)
workflow=$(curl -sS --fail-with-body -H "$auth" "https://api.github.com/repos/$repo/contents/.github/workflows/ivx-e2e.yml?ref=main" | jq -r .content | tr -d "\n" | base64 -d | perl -0pe "s/Run Maestro flows \(dry\)/Run Maestro launch flow/; s#~/.maestro/bin/maestro test expo/\.maestro --format junit --output maestro-report\.xml#~/.maestro/bin/maestro test expo/.maestro/ivx-app-launch.yaml --format junit --output maestro-report.xml#")
entries="[]"
make_blob() { local path="$1"; local content="$2"; local sha; sha=$(jq -n --arg content "$content" "{content:\$content,encoding:\"utf-8\"}" | curl -sS --fail-with-body -X POST -H "$auth" -H "Accept: application/vnd.github+json" -H "Content-Type: application/json" "https://api.github.com/repos/$repo/git/blobs" --data-binary @- | jq -r .sha); entries=$(printf "%s" "$entries" | jq --arg path "$path" --arg sha "$sha" ". + [{path:\$path,mode:\"100644\",type:\"blob\",sha:\$sha}]"); }
make_blob "expo/.maestro/ivx-chat-qa-full.yaml" "$flow"
make_blob "expo/.maestro/ivx-app-launch.yaml" "$launch"
make_blob "expo/.maestro/ivx-owner-ai-chat.yaml" "$owner"
make_blob "expo/playwright.config.ts" "$config"
make_blob "expo/__tests__/e2e/ivx-owner-ai-smoke.spec.ts" "$spec"
make_blob ".github/workflows/ivx-e2e.yml" "$workflow"
tree=$(jq -n --arg base_tree "$base_tree" --argjson tree "$entries" "{base_tree:\$base_tree,tree:\$tree}" | curl -sS --fail-with-body -X POST -H "$auth" -H "Accept: application/vnd.github+json" -H "Content-Type: application/json" "https://api.github.com/repos/$repo/git/trees" --data-binary @- | jq -r .sha)
commit=$(jq -n --arg message "fix(e2e): restore production web coverage and valid Maestro flows" --arg tree "$tree" --arg parent "$parent" "{message:\$message,tree:\$tree,parents:[\$parent]}" | curl -sS --fail-with-body -X POST -H "$auth" -H "Accept: application/vnd.github+json" -H "Content-Type: application/json" "https://api.github.com/repos/$repo/git/commits" --data-binary @- | jq -r .sha)
jq -n --arg sha "$commit" "{sha:\$sha,force:false}" | curl -sS --fail-with-body -X PATCH -H "$auth" -H "Accept: application/vnd.github+json" -H "Content-Type: application/json" "https://api.github.com/repos/$repo/git/refs/heads/main" --data-binary @- >/dev/null
printf "%s\n" "$commit"'

